// Shared pre-pass for reading numbers and symbols aloud (all 12 languages): a line-by-line port of
// training/data_pipeline_multi/pivo_multi/semiotic.py (see its docstring for every rule). It runs first in
// normalizeNumbers (numbers_multi.js), normalizeKannadaText and normalizeIndianEnglish (frontend.js) and must
// give exactly the same text as the Python version (web/tests/numbers_parity.*).
//
//   prenormalize(text, lang, extra) -> text
//
// Words: semiotic_words.js, generated by web/build.py from pivo_multi/semiotic.json.
import WORDS from "./semiotic_words.js";

export { WORDS };

const EN_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September",
  "October", "November", "December"];
const MONTH_INDEX = {};
EN_MONTHS.forEach((m, i) => {
  for (const form of [m, m.toUpperCase(), m.slice(0, 3), m.slice(0, 3).toUpperCase()]) MONTH_INDEX[form] = i + 1;
});
MONTH_INDEX.Sept = MONTH_INDEX.SEPT = 9;

const byLengthThenText = (a, b) => b.length - a.length || (a < b ? -1 : a > b ? 1 : 0);
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&");
const MON = Object.keys(MONTH_INDEX).sort(byLengthThenText).join("|");

const VULGAR = { "½": "1/2", "⅓": "1/3", "⅔": "2/3", "¼": "1/4", "¾": "3/4", "⅕": "1/5", "⅖": "2/5", "⅗": "3/5",
  "⅘": "4/5", "⅙": "1/6", "⅚": "5/6", "⅛": "1/8", "⅜": "3/8", "⅝": "5/8", "⅞": "7/8" };
const SUPERSCRIPT = { "⁰": "0", "¹": "1", "⁴": "4", "⁵": "5", "⁶": "6", "⁷": "7", "⁸": "8", "⁹": "9" };
const ROMAN = { I: 1, II: 2, III: 3, IV: 4, V: 5, VI: 6, VII: 7, VIII: 8, IX: 9, X: 10, XI: 11, XII: 12, XIII: 13,
  XIV: 14, XV: 15, XVI: 16, XVII: 17, XVIII: 18, XIX: 19, XX: 20 };
const ROMAN_KEYWORDS = ["Chapter", "Part", "Volume", "Vol.", "Class", "Phase", "Section", "Article", "Schedule", "Book",
  "Act", "Grade", "Standard", "Std.", "Plan", "Round", "Level", "Season", "World War", "Edition", "Unit", "Paper",
  "Term", "Episode", "Stage", "Tier", "Division", "Rule", "Clause"];
const LATIN_ABBR = { "ext.": "extension", "Ext.": "extension", "e.g.": "for example", "i.e.": "that is",
  "approx.": "approximately", "Ltd.": "limited", "Pvt.": "private", "Govt.": "government", "Jr.": "junior",
  "Sr.": "senior", "Dept.": "department", "Rd.": "road", "Estd.": "established", "Max.": "maximum", "Min.": "minimum" };
const PHONE_WORDS_EN = ["phone", "Phone", "PHONE", "ph", "Ph", "mob", "Mob", "mobile", "Mobile", "call", "Call",
  "tel", "Tel", "telephone", "Telephone", "contact", "Contact", "dial", "Dial", "fax", "Fax", "helpline", "Helpline",
  "whatsapp", "WhatsApp", "Whatsapp", "cell", "Cell", "landline", "Landline", "toll free", "Toll free", "Toll Free",
  "toll-free", "Toll-free"];
const NUMBER_TAILS = new Set(["st", "nd", "rd", "th", "am", "pm", "AM", "PM", "K", "k", "s", "x", "X", "L", "l", "m",
  "g", "W", "V", "km", "kg", "cm", "mm", "ml", "mL", "gm", "ltr", "Ltr", "mg", "hr", "hrs", "Hrs", "min", "mins",
  "sec", "secs", "ms", "GB", "MB", "KB", "TB", "MP", "Hz", "kHz", "MHz", "GHz", "kW", "kWh", "mAh", "Mbps", "Gbps",
  "mph", "kmph", "ft", "lb", "lbs", "oz", "ha", "yr", "yrs", "kms", "Km", "KM", "Kg", "KG", "cr", "Cr", "mn", "bn",
  "lakh", "lakhs", "crore", "crores", "C", "F"]);

const NATIVE_DIGITS = {};
for (let base = 0x900; base < 0xd80; base += 0x80) {
  for (let d = 0; d < 10; d++) NATIVE_DIGITS[String.fromCodePoint(base + 0x66 + d)] = String(d);
}
const DROP = /[\u2122\u00ae\ufe0f\ufe0e\u20e3\u200b]/gu;

/** re.sub with a Python-like match object: m[0], m[1] ... (undefined -> null). */
function sub(re, fn, text) {
  return text.replace(re, (...args) => {
    let end = args.length - 2;
    if (typeof args[args.length - 1] === "object" && args[args.length - 1] !== null) end -= 1;
    const m = args.slice(0, end).map((v) => (v === undefined ? null : v));
    return fn(m);
  });
}
const R = (src) => new RegExp(src, "gu");

const pick = (form, one) => (typeof form === "string" ? form : form[one ? 0 : 1]);
const digitsOf = (s, W) => Array.from(s).filter((c) => c >= "0" && c <= "9").map((c) => W.digits[+c]).join(" ");
const phone = (groups, W, plus = false) => " " + (plus ? W.plus + " " : "")
  + groups.filter((g) => g).map((g) => digitsOf(g, W)).join(", ") + " ";
const pad2 = (n) => String(n).padStart(2, "0");
const dateOf = (day, month, year) => (month >= 1 && month <= 12 && day >= 1 && day <= 31
  ? `${pad2(day)}/${pad2(month)}/${year}` : null);
const fill = (template, parts) => Object.entries(parts).reduce((t, [k, v]) => t.replaceAll("{" + k + "}", v), template);
const mer = (token) => token.replaceAll(".", "").replaceAll(" ", "").toLowerCase();
const ordinalDigits = (n) => (([11, 12, 13].includes(n % 100)) ? `${n}th` : `${n}` + ({ 1: "st", 2: "nd", 3: "rd" }[n % 10] ?? "th"));
const allDigits = (s) => s.match(/[0-9]+/g) ?? [];
const L = "A-Za-z\\u0900-\\u0D7F";

export function prenormalize(text, lang, extra = null) {
  const W = { ...WORDS[lang], ...(extra ?? {}) };
  const en = lang === "en";
  text = Array.from(text.normalize("NFC"), (c) => NATIVE_DIGITS[c] ?? c).join("");
  text = text.replaceAll("\u00a0", " ").replaceAll("\u2009", " ").replaceAll("\u202f", " ");

  // ---- symbols that are never read, and money's "/-"
  text = text.replace(DROP, "");
  text = text.replace(/(?:(?<![A-Za-z])[Cc]opyright\s?)?©/gu, " " + W.copyright + " ");
  text = text.replace(/(?<=[0-9])\s?\/-/gu, "");
  text = text.replaceAll("\\", " ");
  // ---- dashes and minus between numbers -> "-"
  text = text.replace(/(?<=[0-9])\s?[\u2013\u2014\u2012]\s?(?=[0-9])/gu, "-");
  text = text.replaceAll("\u2212", "-");
  // ---- vulgar fractions: 1½ -> 1 1/2
  for (const [ch, frac] of Object.entries(VULGAR)) {
    text = text.replace(R(`(?<=[0-9])${ch}`), " " + frac);
    text = text.replaceAll(ch, " " + frac + " ");
  }

  // ---- electronic: e-mail, URL, bare domain, @handle, #tag
  const spellPart = (part) => {
    const out = [];
    for (const piece of part.split(/([._\-/:])/u)) {
      if ([".", "_", "-", "/", ":"].includes(piece)) {
        out.push({ ".": W.dot, "_": W.underscore, "-": W.hyphen, "/": W.slash, ":": "" }[piece]);
      } else if (/^[0-9]+$/u.test(piece)) {
        out.push(digitsOf(piece, W));
      } else if (piece) {
        out.push(piece);
      }
    }
    return out.filter((w) => w).join(" ");
  };
  text = sub(/(?<![A-Za-z0-9._%+-])([A-Za-z0-9._%+-]+)@([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+)(?![A-Za-z0-9])/gu,
    (m) => " " + spellPart(m[1]) + " " + W.at + " " + spellPart(m[2]) + " ", text);
  const tlds = "com|org|net|in|co|io|ai|gov|edu|info|app|dev|uk|us|me|tv|biz|ac|nic|res";
  text = sub(R(String.raw`(^|[\s(])(?:https?:\/\/)?((?:www\.)?[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.(?:${tlds})`
    + String.raw`(?:\.(?:in|uk|au))?(?:\/[A-Za-z0-9._~\/-]*)?)(?=[\s,;:!?)]|\.(?:\s|$)|$)`), (m) => {
    const body = m[2].replace(/\/+$/u, "");
    const cut = body.indexOf("/");
    let host = cut < 0 ? body : body.slice(0, cut);
    const path = cut < 0 ? "" : body.slice(cut + 1);
    const words = [];
    if (host.toLowerCase().startsWith("www.")) {
      words.push("W W W");
      host = host.slice(4);
    }
    words.push(spellPart(host));
    if (path) words.push(W.slash + " " + spellPart(path));
    return m[1] + words.join(" ") + " ";
  }, text);
  text = text.replace(/(?<![A-Za-z0-9])https?:\/\//gu, "");
  text = sub(/(^|\s)@([A-Za-z_][A-Za-z0-9_]*)/gu, (m) => m[1] + W.at + " " + m[2].replaceAll("_", " "), text);
  text = sub(/(^|\s)#([A-Za-z][A-Za-z0-9_]*)/gu, (m) => m[1] + W.hashtag + " " + m[2].replaceAll("_", " "), text);
  // number signs: #5, № 5, No. 5
  text = text.replace(/(?:#|№|(?<![A-Za-z0-9_])No\.|(?<![A-Za-z0-9_])NO\.)\s?(?=[0-9])/gu, " " + W.number + " ");

  // ---- dates
  const mon = (token) => MONTH_INDEX[token.replace(/\.+$/u, "")];
  const ordsuf = "(?:st|nd|rd|th)?";
  text = sub(R(String.raw`(?<![0-9])([0-9]{1,2})${ordsuf}\s?(?:of\s)?(${MON})\.?,?\s([0-9]{4})(?![0-9])`),
    (m) => dateOf(+m[1], mon(m[2]), +m[3]) ?? m[0], text);
  text = sub(R(String.raw`(?<![A-Za-z])(${MON})\.?\s([0-9]{1,2})${ordsuf},?\s([0-9]{4})(?![0-9])`),
    (m) => dateOf(+m[2], mon(m[1]), +m[3]) ?? m[0], text);
  text = sub(/(?<![0-9./-])([0-9]{1,2})[/.-]([0-9]{1,2})[/.-]([0-9]{4})(?![0-9]|[.,/-][0-9])/gu,
    (m) => dateOf(+m[1], +m[2], +m[3]) ?? m[0], text);
  text = sub(/(?<![0-9./-])([0-9]{4})([/.-])([0-9]{1,2})\2([0-9]{1,2})(?![0-9]|[.,/-][0-9])/gu,
    (m) => dateOf(+m[4], +m[3], +m[1]) ?? m[0], text);
  text = sub(/(?<![0-9./-])([0-9]{4})[/.]([0-9]{1,2})[/.]([0-9]{1,2})(?![0-9])/gu,
    (m) => dateOf(+m[3], +m[2], +m[1]) ?? m[0], text);
  text = sub(/(?<![0-9./-])([0-9]{1,2})([/.-])([0-9]{1,2})\2([0-9]{2})(?![0-9]|[.,/-][0-9])/gu,
    (m) => dateOf(+m[1], +m[3], (+m[4] <= 49 ? 2000 : 1900) + +m[4]) ?? m[0], text);
  const months = W.months;
  const monthName = (n) => (en ? EN_MONTHS[n - 1] : months[n - 1]);
  text = sub(R(String.raw`(?<![0-9])([0-9]{1,2})(${ordsuf})\s?(?:of\s)?(${MON})\.?(?![A-Za-z])`),
    (m) => (+m[1] >= 1 && +m[1] <= 31 ? `${m[1]}${en ? m[2] : ""} ${monthName(mon(m[3]))}` : m[0]), text);
  text = sub(R(String.raw`(?<![A-Za-z])(${MON})\.?\s([0-9]{1,2})(${ordsuf})(?![0-9])`),
    (m) => (+m[2] >= 1 && +m[2] <= 31
      ? (en ? `${monthName(mon(m[1]))} ${m[2]}${m[3]}` : `${m[2]} ${monthName(mon(m[1]))}`) : m[0]), text);
  text = sub(R(String.raw`(?<![A-Za-z])(${MON})\.?,?\s(?=[0-9]{4}(?![0-9]))`), (m) => monthName(mon(m[1])) + " ", text);

  // ---- telephone numbers
  text = sub(/(?<![0-9+])\+(?!91[\s-]?[6-9][0-9]{4}[\s-]?[0-9]{5}(?![0-9]))([0-9]{1,3})((?:(?:[\s-]+|(?<=\)))[0-9]{1,5}|[\s-]*\([0-9]{1,5}\)){2,6})(?![0-9])/gu,
    (m) => (m[0].replace(/[^0-9]/gu, "").length >= 8 ? phone([m[1], ...allDigits(m[2])], W, true) : m[0]), text);
  text = sub(/(?<![0-9])\((0?[0-9]{2,5})\)[\s-]*([0-9]{2,5})(?:[\s-]([0-9]{2,5}))?(?![0-9])/gu,
    (m) => phone([m[1], m[2], m[3]], W), text);
  text = sub(/(?<![0-9.,])(0[0-9]{1,4})((?:[\s-][0-9]{2,5}){2,3})(?![0-9]|[.,][0-9])/gu,
    (m) => phone([m[1], ...allDigits(m[2])], W), text);
  text = sub(/(?<![0-9.,])(1[89]00|1860)[\s-]?([0-9]{2,4})[\s-]?([0-9]{3,4})(?![0-9])/gu,
    (m) => phone([m[1], m[2], m[3]], W), text);
  text = sub(/(?<![0-9.,])([0-9]{3})-([0-9]{3})-([0-9]{4})(?![0-9])/gu, (m) => phone([m[1], m[2], m[3]], W), text);
  const phoneWords = [...PHONE_WORDS_EN, ...(W.phone_words ?? [])];
  const alt = [...phoneWords].sort(byLengthThenText).map(escapeRe).join("|");
  text = sub(R(String.raw`((?<![${L}])(?:${alt})(?![${L}])\.?(?:\s?(?:[Nn]o\.?|[Nn]umber|#))?\s?:?\s?)`
    + String.raw`(?<![0-9])([0-9]{2,5}(?:[\s-][0-9]{2,5}){0,3})(?![0-9]|[.,][0-9])`),
  (m) => (m[2].replace(/[^0-9]/gu, "").length >= 6 && !/^[6-9][0-9]{4}[\s-]?[0-9]{5}$/u.test(m[2])
    ? m[1] + phone(allDigits(m[2]), W) : m[0]), text);

  // ---- times
  const ampm = String.raw`[AaPp](?:\.\s?[Mm]\.|\s?[Mm](?![A-Za-z]))`;
  text = sub(R(String.raw`(?<![0-9:])(?<![0-9]\.)([01]?[0-9]|2[0-3])[.:]([0-5][0-9])\s?(${ampm})([A-Za-z]?)`), // "p.m.km": keep a space
    (m) => `${m[1]}:${m[2]} ${mer(m[3])}` + (m[4] ? " " + m[4] : ""), text);
  text = sub(R(String.raw`(?<![0-9:])(?<![0-9][.,])(1[0-2]|0?[1-9])\s?(${ampm})([A-Za-z]?)`),
    (m) => `${m[1]}:00 ${mer(m[2])}` + (m[3] ? " " + m[3] : ""), text);
  if (en) {
    text = text.replace(/(?<![0-9:])12(?::00)?\s?(noon|midnight)(?![A-Za-z0-9_])/gu, "12 $1");
  } else {
    text = text.replace(/(?<![0-9:])12(?::00)?\s?noon(?![A-Za-z0-9_])/gu, "12:00 pm");
    text = text.replace(/(?<![0-9:])12(?::00)?\s?midnight(?![A-Za-z0-9_])/gu, "12:00 am");
  }
  text = sub(R(String.raw`(?<![0-9:])([01]?[0-9]|2[0-3]):([0-5][0-9]):([0-5][0-9])(?:\s?(${ampm}))?(?![0-9])`), (m) => {
    const [hour, minute, sec] = [m[1], m[2], +m[3]];
    const tail = m[4] ? " " + mer(m[4]) : "";
    if (!sec) return `${hour}:${minute}${tail}`;
    const conj = W.and ? W.and + " " : "";
    return `${hour}:${minute}${tail} ${conj}${sec} ${pick(W.seconds, sec === 1)}`;
  }, text);
  const clock = String.raw`(?:[01]?[0-9]|2[0-3]):[0-5][0-9](?:\s?${ampm})?`;
  const rng = W.range;
  text = sub(R(String.raw`(?<![0-9:])(${clock})\s?(?:-|to|till|until)\s?(${clock})(?![0-9])`),
    (m) => m[1].trimEnd() + rng[0] + (rng[1] ? " " + rng[1] : "") + " " + m[2], text);

  // ---- decades (English handles its own)
  if (!en) {
    text = sub(/(?<![0-9])(1[0-9][0-9]0|20[0-9]0)(?:'s|’s|s)(?![A-Za-z])/gu, (m) => fill(W.decade, { y: m[1] }), text);
  }

  // ---- roman numerals
  const kw = [...ROMAN_KEYWORDS].sort(byLengthThenText).map(escapeRe).join("|");
  text = sub(R(String.raw`(?<![A-Za-z])(${kw})\s(X{0,2}(?:IX|IV|V?I{0,3}))(?![A-Za-z])`),
    (m) => (ROMAN[m[2]] ? `${m[1]} ${ROMAN[m[2]]}` : m[0]), text);
  text = sub(/(?<![A-Za-z])([A-Z][a-z]{2,})\s(II|III|IV|VI|VII|VIII|IX|XI|XII|XIII|XIV|XV)(?![A-Za-z])/gu,
    (m) => `${m[1]} ${en ? "the " : ""}${ordinalDigits(ROMAN[m[2]])}`, text);

  // ---- dotted numbers: versions, sections, IP addresses
  text = sub(/(?<![0-9.])([0-9]+(?:\.[0-9]+){2,})(?![0-9]|\.[0-9])/gu,
    (m) => " " + m[1].split(".").join(" " + W.dot + " ") + " ", text);
  text = text.replace(/(?<![^\s(])\.([0-9])/gu, "0.$1");                      // " .5" -> " 0.5"

  // ---- serial codes: letters and digits apart (COVID-19, AI-202, KA-01-AB-1234, 4G, H2O)
  text = sub(/(?<![A-Za-z0-9])[A-Za-z0-9]+(?:\.[0-9]+)?(?:-[A-Za-z0-9]+)*(?![A-Za-z0-9])/gu, (m) => {
    const token = m[0];
    if (!(/[A-Za-z]/u.test(token) && /[0-9]/u.test(token))) return token;
    const tail = /^([0-9]+(?:\.[0-9]+)?)([A-Za-z]+)$/u.exec(token);
    if (tail && NUMBER_TAILS.has(tail[2])) return token;
    if (/^[0-9]+(?:st|nd|rd|th)$/u.test(token) || /[A-Za-z]\./u.test(token)) return token; // 21st, "Prof.2", "p.m.8"
    // split only where letters meet digits; "13-12" keeps its dash, "51st" stays an ordinal
    return token.replace(/(?<=[A-Za-z])-?(?=[0-9])|(?<=[0-9])-?(?=[A-Za-z])(?!(?:st|nd|rd|th)(?![a-z]))/gu, " ");
  }, text);

  // ---- scale letters after numbers: 10K -> 10000
  text = sub(/(?<![0-9.])([0-9]{1,4}(?:\.[0-9]+)?)[Kk](?![A-Za-z0-9])/gu, (m) => {
    const [whole, frac = ""] = m[1].split(".");
    if (frac.length > 3) return m[0];
    return String(BigInt(whole + frac.padEnd(3, "0")));
  }, text);

  // ---- feet and inches: 5'11", 5 ft 11 in
  text = sub(/(?<![0-9])([0-9]{1,2})\s?['’]\s?([0-9]{1,2})\s?(?:"|”|'')/gu,
    (m) => `${m[1]} ${W.feet} ${m[2]} ${W.inches}`, text);
  text = sub(/(?<![0-9])([0-9]{1,2})\s?(?:ft|feet)\s([0-9]{1,2})\s?(?:in|inch|inches)(?![A-Za-z])/gu,
    (m) => `${m[1]} ${W.feet} ${m[2]} ${W.inches}`, text);

  // ---- fractions (English reads its own) and ratios
  if (!en) {
    const special = { "1/2": W.half, "1/4": W.quarter, "3/4": W.three_quarters };
    text = sub(/(?<![0-9/.])(?:([0-9]{1,3})\s)?([1-9][0-9]{0,2}(?:\.[0-9]+)?)\/([1-9][0-9]{0,2})(?![0-9/]|[.-][0-9])/gu, (m) => {
      const words = special[`${m[2]}/${m[3]}`] || fill(W.fraction, { a: m[2], b: m[3] });
      if (m[1]) return `${m[1]} ${W.and ? W.and + " " : ""}${words}`;
      return words;
    }, text);
  }
  text = sub(/(?<![0-9:.])([0-9]{1,3})(?::([0-9])|\s:\s([0-9]{1,3}))(?![0-9:])/gu,
    (m) => " " + fill(W.ratio, { a: m[1], b: m[2] || m[3] }) + " ", text);

  // ---- math
  text = text.replace(/(?<=[0-9])\s?[×xX*]\s?(?=[0-9])/gu, " " + W.times + " ");
  text = text.replace(/\s?×\s?/gu, " " + W.times + " ");
  text = text.replace(/\s?÷\s?/gu, " " + W.divided_by + " ");
  text = text.replace(/(?<=[0-9A-Za-z])\s?\^\s?(?=[0-9A-Za-z])/gu, " " + W.power + " ");
  text = text.replaceAll("±", " " + W.plus_minus + " ");
  text = text.replace(/(?<=[0-9A-Za-z])\s?<\s?(?=[0-9A-Za-z])/gu, " " + W.less_than + " ");
  text = text.replace(/(?<=[0-9A-Za-z])\s?>\s?(?=[0-9A-Za-z])/gu, " " + W.greater_than + " ");
  if (en) text = text.replace(/\s?=\s?/gu, " " + W.equals + " ");
  text = text.replace(/[~≈]\s?(?=[0-9])/gu, W.about + " ");
  text = squares(text, W);
  text = sub(/([0-9A-Za-z])([⁰¹⁴⁵⁶⁷⁸⁹]+)/gu,
    (m) => m[1] + " " + W.power + " " + Array.from(m[2], (c) => SUPERSCRIPT[c]).join("") + " ", text);

  // ---- Latin abbreviations used in Indian English and mixed text
  for (const [short, full] of Object.entries(LATIN_ABBR)) text = text.replace(R(`(?<![A-Za-z])${escapeRe(short)}`), " " + full + " ");
  text = text.replace(/(?<![A-Za-z])etc\.?(?![A-Za-z])/gu, " " + W.etc + " ");
  // word/word -> "word slash word" (Yes/No, and/or); "60 km/h" is a unit and stays
  text = sub(/(?<![0-9A-Za-z\u0900-\u0D7F])(?<![0-9]\s)([A-Za-z\u0900-\u0D7F]+)\/(?=[A-Za-z\u0900-\u0D7F])/gu,
    (m) => m[1] + " " + W.slash + " ", text);
  return text;
}

/** x² -> x squared, 5³ -> 5 cubed; m² / km² / ft³ stay (they are units). */
function squares(text, W) {
  const chars = Array.from(text);
  const out = [];
  const asciiLetter = (c) => /^[A-Za-z]$/u.test(c);
  chars.forEach((ch, i) => {
    if (ch === "²" || ch === "³") {
      let k = i;
      while (k > 0 && asciiLetter(chars[k - 1])) k--;
      const unit = chars.slice(k, i).join("");
      if (["km", "cm", "mm", "ft", "m"].includes(unit) && (k === 0 || !/^\p{L}$/u.test(chars[k - 1]))) {
        out.push(ch);
        return;
      }
      out.push(" " + (ch === "²" ? W.squared : W.cubed) + " ");
      return;
    }
    out.push(ch);
  });
  return out.join("");
}
